import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

/**
 * Auction item, prices in item currency.
 *
 * @trace DSN-015 REQ-001 REQ-002 REQ-004 REQ-009
 */
export class Item {
  constructor(public id: string, public sellerId: string, public title: string, public startingPrice: number, public currency: Currency, public endTime: Date, public status: AuctionStatus, public highestBidAmount: number | null, public highestBidderId: string | null, public winnerId: string | null) {}

  /** Returns true when the status is open and the end time has not been reached at the given instant. */
  isOpen(now: Date): boolean {
    return this.status === AuctionStatus.open && now.getTime() < this.endTime.getTime();
  }

  /** Returns the lowest amount a next bid may have: the starting price, or one unit above the highest bid. */
  minimumBid(): number {
    return this.highestBidAmount === null ? this.startingPrice : this.highestBidAmount + 1;
  }

  /** Adds 2 minutes to the end time when an open auction is within its last 2 minutes at the given instant, and returns whether it was extended. */
  extendIfLate(now: Date): boolean {
    if (!this.isOpen(now)) {
      return false;
    }
    const remainingMs = this.endTime.getTime() - now.getTime();
    if (remainingMs > 2 * 60 * 1000) {
      return false;
    }
    this.endTime = new Date(this.endTime.getTime() + 2 * 60 * 1000);
    return true;
  }
}

import { randomUUID } from 'node:crypto';
import { User } from './User.js';
import { UserStore } from './UserStore.js';

/**
 * Validates display names and issues one user id per name.
 *
 * @trace DSN-021 REQ-008
 */
export class UserService {
  constructor(private readonly userStore: UserStore) {}

  /** Registers a display name of 2 to 20 characters and returns the new user; throws if invalid or already taken. */
  async register(displayName: string): Promise<User> {
    if (typeof displayName !== 'string') {
      throw new Error('displayName must be a string');
    }
    const name = displayName.trim();
    if (name.length < 2 || name.length > 20) {
      throw new Error('displayName must be between 2 and 20 characters');
    }
    const existing = await this.userStore.findByName(name);
    if (existing !== null) {
      throw new Error(`displayName ${name} is already taken`);
    }
    return this.userStore.save(new User(randomUUID(), name));
  }
}

