import { ItemService } from './ItemService.js';

/**
 * Periodic job that closes auctions whose end time was reached.
 *
 * @trace DSN-024 REQ-004
 */
export class AuctionCloser {
  private timer: ReturnType<typeof setInterval> | undefined;

  constructor(private readonly itemService: ItemService, public intervalMs: number) {
    if (!Number.isInteger(intervalMs) || intervalMs <= 0) {
      throw new Error('intervalMs must be a positive integer');
    }
  }

  /** Closes every auction whose end time has been reached at the current moment. */
  async tick(): Promise<void> {
    await this.itemService.closeDueAuctions(new Date());
  }
}

import { Item } from './Item.js';
import { ItemView } from './ItemView.js';
import { ItemService } from './ItemService.js';
import { ExchangeRateService } from '../exchange-rates/ExchangeRateService.js';
import { Currency } from './Currency.js';

/**
 * HTTP-facing item operations: listing items, viewing items with display-currency prices, and listing open auctions.
 * @trace DSN-019 REQ-001 REQ-005 REQ-004
 */
export class ItemController {
  constructor(private readonly itemService: ItemService, private readonly exchangeRateService: ExchangeRateService) {}

  /** Lists a new item for a seller; throws Error when a field is missing or invalid. */
  async listItem(userId: string, title: string, startingPrice: number, endTime: string, currency: string): Promise<Item> {
    if (typeof userId !== 'string' || userId.length === 0) {
      throw new Error('userId is required');
    }
    if (typeof title !== 'string' || title.trim().length === 0) {
      throw new Error('title is required');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('startingPrice must be a non-negative number');
    }
    if (typeof endTime !== 'string' || endTime.length === 0) {
      throw new Error('endTime is required');
    }
    const end = new Date(endTime);
    if (Number.isNaN(end.getTime())) {
      throw new Error('endTime must be a valid date');
    }
    if (!this.isCurrency(currency)) {
      throw new Error('currency must be one of CHF, EUR, USD');
    }
    return this.itemService.listItem(userId, title, startingPrice, end, currency);
  }

  /** Returns an item with prices converted to the display currency when one is given; throws Error for an invalid id or currency, or when the item is not found. */
  async getItem(id: string, displayCurrency: string | undefined): Promise<ItemView> {
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('id is required');
    }
    if (displayCurrency !== undefined && !this.isCurrency(displayCurrency)) {
      throw new Error('displayCurrency must be one of CHF, EUR, USD');
    }
    const item = await this.itemService.getItem(id);
    if (displayCurrency === undefined) {
      return { item, displayCurrency: null, convertedStartingPrice: null, convertedHighestBid: null };
    }
    const target = displayCurrency as Currency;
    const convertedStartingPrice = await this.exchangeRateService.convert(item.startingPrice, item.currency, target);
    const convertedHighestBid =
      item.highestBidAmount === null
        ? null
        : await this.exchangeRateService.convert(item.highestBidAmount, item.currency, target);
    return { item, displayCurrency: target, convertedStartingPrice, convertedHighestBid };
  }

  /** Returns all auctions that are currently open for bidding. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemService.listOpenItems();
  }

  private isCurrency(value: string): value is Currency {
    return (Object.values(Currency) as string[]).includes(value);
  }
}

import { randomUUID } from 'node:crypto';
import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { UserStore } from './UserStore.js';
import { AuctionEventPublisher } from './AuctionEventPublisher.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

const ALLOWED_CURRENCIES: string[] = [Currency.CHF, Currency.EUR, Currency.USD];

/**
 * Creates and reads items, and closes auctions whose end time has been reached.
 *
 * @trace DSN-022 REQ-001 REQ-004
 */
export class ItemService {
  constructor(private readonly itemStore: ItemStore, private readonly userStore: UserStore, private readonly auctionEventPublisher: AuctionEventPublisher) {}

  /** Lists a new open item for an existing seller; throws on invalid input or unknown seller. */
  async listItem(sellerId: string, title: string, startingPrice: number, endTime: Date, currency: string): Promise<Item> {
    if (typeof sellerId !== 'string' || sellerId.trim() === '') {
      throw new Error('sellerId must be a non-empty string');
    }
    if (typeof title !== 'string' || title.trim() === '') {
      throw new Error('title must be a non-empty string');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('startingPrice must be a non-negative number');
    }
    if (!(endTime instanceof Date) || Number.isNaN(endTime.getTime())) {
      throw new Error('endTime must be a valid date');
    }
    if (typeof currency !== 'string' || !ALLOWED_CURRENCIES.includes(currency)) {
      throw new Error('currency must be one of CHF, EUR, USD');
    }
    const seller = await this.userStore.findById(sellerId);
    if (seller === null) {
      throw new Error(`User ${sellerId} not found`);
    }
    const item = new Item(
      randomUUID(),
      sellerId,
      title,
      startingPrice,
      currency as Currency,
      endTime,
      AuctionStatus.open,
      null,
      null,
      null,
    );
    return this.itemStore.saveItem(item);
  }

  /** Returns the item with the given id; throws if the id is invalid or the item is not found. */
  async getItem(id: string): Promise<Item> {
    if (typeof id !== 'string' || id.trim() === '') {
      throw new Error('id must be a non-empty string');
    }
    const item = await this.itemStore.findItem(id);
    if (item === null) {
      throw new Error(`Item ${id} not found`);
    }
    return item;
  }

  /** Returns all items whose auctions are open. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemStore.findOpenItems();
  }

  /** Closes every auction due at the given time, sets the winner or unsold status, and publishes each close. */
  async closeDueAuctions(now: Date): Promise<void> {
    if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
      throw new Error('now must be a valid date');
    }
    const dueItems = await this.itemStore.findDueItems(now);
    for (const item of dueItems) {
      if (item.highestBidderId === null || item.highestBidAmount === null) {
        item.status = AuctionStatus.unsold;
        item.winnerId = null;
      } else {
        item.status = AuctionStatus.closed;
        item.winnerId = item.highestBidderId;
      }
      await this.itemStore.saveItem(item);
      await this.auctionEventPublisher.publishAuctionClosed(item);
    }
  }
}

import { randomUUID } from 'node:crypto';
import { Bid } from './Bid.js';
import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { UserStore } from './UserStore.js';
import { BidEventPublisher } from './BidEventPublisher.js';

/**
 * Validates and stores bids, extends end time, publishes events to the event feed.
 *
 * @trace DSN-023 REQ-002 REQ-009 REQ-003 REQ-011
 */
export class BidService {
  constructor(
    private readonly itemStore: ItemStore,
    private readonly bidEventPublisher: BidEventPublisher,
    private readonly userStore: UserStore,
  ) {}

  /** Accepts a valid bid, stores it, extends a late auction and publishes it; throws if the item or bidder is not found or the bid is invalid. */
  async placeBid(itemId: string, bidderId: string, amount: number): Promise<Bid> {
    if (typeof itemId !== 'string' || itemId.length === 0) {
      throw new Error('itemId must be a non-empty string');
    }
    if (typeof bidderId !== 'string' || bidderId.length === 0) {
      throw new Error('bidderId must be a non-empty string');
    }
    if (typeof amount !== 'number' || !Number.isFinite(amount) || amount <= 0) {
      throw new Error('amount must be a positive number');
    }

    const item: Item | null = await this.itemStore.findItem(itemId);
    if (item === null) {
      throw new Error(`Item ${itemId} not found`);
    }
    const bidder = await this.userStore.findById(bidderId);
    if (bidder === null) {
      throw new Error(`User ${bidderId} not found`);
    }

    const now = new Date();
    if (!item.isOpen(now)) {
      throw new Error(`Item ${itemId} is not open for bids`);
    }
    if (item.sellerId === bidderId) {
      throw new Error('The seller cannot bid on their own item');
    }
    const minimum = item.minimumBid();
    if (amount < minimum) {
      throw new Error(`Bid must be at least ${minimum}`);
    }

    item.extendIfLate(now);
    const bid = new Bid(randomUUID(), itemId, bidderId, amount, now);
    const storedBid = await this.itemStore.saveBid(bid);
    await this.itemStore.saveItem(item);
    await this.bidEventPublisher.publishBidAccepted(storedBid, item);
    return storedBid;
  }
}

import { DatabaseSync } from 'node:sqlite';
import { User } from './User.js';

/**
 * Persists users with a unique display name in the API server's SQLite database.
 *
 * @trace DSN-028 REQ-008
 */
export class UserStore {
  private readonly table = 'users';

  constructor(db: DatabaseSync) {
    this.db = db;
    this.db.exec(
      `CREATE TABLE IF NOT EXISTS ${this.table} (id TEXT PRIMARY KEY, displayName TEXT NOT NULL UNIQUE)`,
    );
  }

  private readonly db: DatabaseSync;

  /** Returns the user with the given display name, or null when none exists. */
  async findByName(displayName: string): Promise<User | null> {
    const rows = this.db
      .prepare(`SELECT id, displayName FROM ${this.table} WHERE displayName = ?`)
      .all(displayName) as unknown as { id: string; displayName: string }[];
    return rows.length > 0 ? new User(rows[0].id, rows[0].displayName) : null;
  }

  /** Stores a new user or updates an existing one by id; throws if the display name is taken by another id. */
  async save(user: User): Promise<User> {
    const existing = this.db
      .prepare(`SELECT id FROM ${this.table} WHERE id = ?`)
      .all(user.id) as unknown as { id: string }[];
    if (existing.length > 0) {
      this.db
        .prepare(`UPDATE ${this.table} SET displayName = ? WHERE id = ?`)
        .run(user.displayName, user.id);
    } else {
      this.db
        .prepare(`INSERT INTO ${this.table} (id, displayName) VALUES (?, ?)`)
        .run(user.id, user.displayName);
    }
    return user;
  }

  /** Returns the user with the given id, or null when none exists; throws if the id is empty. */
  async findById(id: string): Promise<User | null> {
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('id must be a non-empty string');
    }
    const rows = this.db
      .prepare(`SELECT id, displayName FROM ${this.table} WHERE id = ?`)
      .all(id) as unknown as { id: string; displayName: string }[];
    return rows.length > 0 ? new User(rows[0].id, rows[0].displayName) : null;
  }
}

import { Currency } from '../auction-api/Currency.js';
import { FrankfurterClient } from './FrankfurterClient.js';

interface CachedRates {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Converts prices for display using exchange rates cached for a configured time, returning null when no rate is available.
 * @trace DSN-025 REQ-005 REQ-010
 */
export class ExchangeRateService {
  private readonly cache = new Map<Currency, CachedRates>();

  constructor(private readonly frankfurterClient: FrankfurterClient, public cacheTtlMs: number) {}

  /** Converts an amount between currencies for display; returns null when no rate is available, throws on invalid input. */
  async convert(amount: number, from: Currency, to: Currency): Promise<number | null> {
    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error('amount must be a non-negative finite number');
    }
    if (!Object.values(Currency).includes(from)) {
      throw new Error(`from currency ${String(from)} is not supported`);
    }
    if (!Object.values(Currency).includes(to)) {
      throw new Error(`to currency ${String(to)} is not supported`);
    }
    if (from === to) {
      return amount;
    }

    const rates = await this.ratesFor(from);
    if (rates === null) {
      return null;
    }
    const rate = rates[to];
    if (typeof rate !== 'number') {
      return null;
    }
    return Math.round(amount * rate * 100) / 100;
  }

  /** Returns rates for a base currency from the cache or a fresh fetch; returns null when Frankfurter fails and no fresh cache exists. */
  private async ratesFor(base: Currency): Promise<Record<string, number> | null> {
    const cached = this.cache.get(base);
    if (cached && Date.now() - cached.fetchedAt < this.cacheTtlMs) {
      return cached.rates;
    }
    try {
      const rates = await this.frankfurterClient.fetchRates(base);
      this.cache.set(base, { rates, fetchedAt: Date.now() });
      return rates;
    } catch {
      return null;
    }
  }
}

import { Currency } from '../auction-api/Currency.js';

interface CachedRates {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Fetches exchange rates from the Frankfurter API and caches them for one hour.
 * @trace DSN-026 REQ-005 REQ-010
 */
export class FrankfurterClient {
  private static readonly BASE_URL = 'https://api.frankfurter.app';
  private static readonly CACHE_TTL_MS = 60 * 60 * 1000;
  private static readonly TIMEOUT_MS = 5000;

  private readonly cache = new Map<string, CachedRates>();

  constructor() {}

  /**
   * Returns rates for the base currency, using the cache when fresh; returns an empty record when the API is unreachable and no valid cache exists. Throws if the base currency is not CHF, EUR or USD.
   */
  async fetchRates(base: Currency): Promise<Record<string, number>> {
    if (!Object.values(Currency).includes(base)) {
      throw new Error(`Unsupported base currency ${String(base)}`);
    }
    const now = Date.now();
    const cached = this.cache.get(base);
    if (cached && now - cached.fetchedAt < FrankfurterClient.CACHE_TTL_MS) {
      return { ...cached.rates };
    }
    try {
      const response = await fetch(
        `${FrankfurterClient.BASE_URL}/latest?from=${encodeURIComponent(base)}`,
        { signal: AbortSignal.timeout(FrankfurterClient.TIMEOUT_MS) },
      );
      if (!response.ok) {
        throw new Error(`Frankfurter responded with status ${response.status}`);
      }
      const body = (await response.json()) as { rates?: Record<string, number> };
      if (!body.rates || typeof body.rates !== 'object') {
        throw new Error('Frankfurter response has no rates');
      }
      const rates: Record<string, number> = { ...body.rates };
      this.cache.set(base, { rates, fetchedAt: now });
      return { ...rates };
    } catch {
      return {};
    }
  }
}

import { EventFeed } from './EventFeed.js';
import { Item } from './Item.js';

/**
 * Publishes auction closed events to the internal ws event feed.
 *
 * @trace DSN-030 REQ-003 REQ-004 REQ-007
 */
export class AuctionEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes the closed state, winner and final bid of an item to the event feed; throws an Error when the item or its id is missing. */
  async publishAuctionClosed(item: Item): Promise<void> {
    if (!item || typeof item.id !== 'string' || item.id === '') {
      throw new Error('item is required and must have a non-empty id');
    }
    const payload = JSON.stringify({
      itemId: item.id,
      status: item.status,
      winnerId: item.winnerId,
      highestBidAmount: item.highestBidAmount,
      highestBidderId: item.highestBidderId,
    });
    this.eventFeed.publish(`auction.closed.${item.id}`, payload);
  }
}

import { Bid } from './Bid.js';
import { Item } from './Item.js';
import { EventFeed } from './EventFeed.js';

/**
 * Publishes accepted bid events to the internal ws event feed.
 *
 * @trace DSN-031 REQ-003 REQ-007 REQ-011
 */
export class BidEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes an accepted bid to the item's topic; throws an Error when the bid or item is invalid. */
  async publishBidAccepted(bid: Bid, item: Item): Promise<void> {
    if (!bid || typeof bid.id !== 'string' || bid.id.length === 0) {
      throw new Error('bid is invalid');
    }
    if (!item || typeof item.id !== 'string' || item.id.length === 0) {
      throw new Error('item is invalid');
    }
    if (bid.itemId !== item.id) {
      throw new Error(`Bid ${bid.id} does not belong to item ${item.id}`);
    }
    const payload = JSON.stringify({
      bidId: bid.id,
      itemId: bid.itemId,
      bidderId: bid.bidderId,
      amount: bid.amount,
      placedAt: bid.placedAt.toISOString(),
    });
    this.eventFeed.publish(`item:${item.id}`, payload);
  }
}

import WebSocket from 'ws';
import { LiveGateway } from './LiveGateway.js';

const API_SERVER_URL = process.env.API_SERVER_URL ?? 'ws://localhost:8080';

/**
 * Client of the API server's internal event feed that hands incoming events to the live gateway.
 * @trace DSN-032 REQ-003 REQ-007 REQ-011
 */
export class EventFeedClient {
  constructor(private readonly liveGateway: LiveGateway) {}

  /** Opens the ws connection to the API server feed; each received event goes to onEvent. */
  connect(): void {
    const socket = new WebSocket(`${API_SERVER_URL}/internal/live-update-server`);
    socket.on('message', (data: WebSocket.RawData) => {
      try {
        const parsed = JSON.parse(data.toString()) as { topic: string; payload: string };
        this.onEvent(parsed.topic, parsed.payload);
      } catch (error) {
        console.error(`Invalid event from API server: ${(error as Error).message}`);
      }
    });
  }

  /** Broadcasts the message in the payload to watchers of its item; throws Error on an empty topic or malformed payload. */
  onEvent(topic: string, payload: string): void {
    if (typeof topic !== 'string' || topic.length === 0) {
      throw new Error('topic must be a non-empty string');
    }
    let body: { itemId?: unknown; message?: unknown };
    try {
      body = JSON.parse(payload) as { itemId?: unknown; message?: unknown };
    } catch {
      throw new Error('payload must be a JSON string');
    }
    if (typeof body.itemId !== 'string' || body.itemId.length === 0) {
      throw new Error('payload.itemId must be a non-empty string');
    }
    if (typeof body.message !== 'string') {
      throw new Error('payload.message must be a string');
    }
    this.liveGateway.broadcast(body.itemId, body.message);
  }
}

import { WebSocket } from 'ws';

/**
 * WebSocket gateway that holds browser sockets by client id and sends each broadcast only to the clients watching that item.
 * @trace DSN-033 REQ-003 REQ-009 REQ-011 REQ-004
 */
export class LiveGateway {
  private watchers: Map<string, Set<string>> = new Map();

  constructor(public sockets: Map<string, WebSocket>) {}

  /** Registers a client as watching an item; throws Error when an id is empty. */
  watch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    let clients = this.watchers.get(itemId);
    if (!clients) {
      clients = new Set<string>();
      this.watchers.set(itemId, clients);
    }
    clients.add(clientId);
  }

  /** Removes a client from the watchers of an item; throws Error when an id is empty. */
  unwatch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    clients.delete(clientId);
    if (clients.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  /** Sends a message to every open socket whose client watches the item; throws Error when itemId is empty. */
  broadcast(itemId: string, message: string): void {
    this.checkId(itemId, 'itemId');
    const clients = this.watchers.get(itemId);
    if (!clients) {
      return;
    }
    for (const clientId of clients) {
      const socket = this.sockets.get(clientId);
      if (socket && socket.readyState === WebSocket.OPEN) {
        socket.send(message);
      }
    }
  }

  private checkId(value: string, name: string): void {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new Error(`${name} must be a non-empty string`);
    }
  }
}

import { DatabaseSync } from 'node:sqlite';
import { Item } from './Item.js';
import { Bid } from './Bid.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

interface ItemRow {
  id: string;
  sellerId: string;
  title: string;
  startingPrice: number;
  currency: string;
  endTime: string;
  status: string;
  highestBidAmount: number | null;
  highestBidderId: string | null;
  winnerId: string | null;
}

interface BidRow {
  id: string;
  itemId: string;
  bidderId: string;
  amount: number;
  placedAt: string;
}

/**
 * Persists items and bids in the API server's SQLite database.
 * @trace DSN-029 REQ-001 REQ-002 REQ-004
 */
export class ItemStore {
  private readonly db: DatabaseSync;

  constructor(db: DatabaseSync) {
    this.db = db;
    this.db.exec(`CREATE TABLE IF NOT EXISTS items (
      id TEXT PRIMARY KEY,
      sellerId TEXT NOT NULL,
      title TEXT NOT NULL,
      startingPrice REAL NOT NULL,
      currency TEXT NOT NULL,
      endTime TEXT NOT NULL,
      status TEXT NOT NULL,
      highestBidAmount REAL,
      highestBidderId TEXT,
      winnerId TEXT
    )`);
    this.db.exec(`CREATE TABLE IF NOT EXISTS bids (
      id TEXT PRIMARY KEY,
      itemId TEXT NOT NULL,
      bidderId TEXT NOT NULL,
      amount REAL NOT NULL,
      placedAt TEXT NOT NULL
    )`);
  }

  /** Inserts the item if its id is new, otherwise updates the stored row. */
  async saveItem(item: Item): Promise<Item> {
    const existing = this.db
      .prepare('SELECT id FROM items WHERE id = ?')
      .all(item.id) as unknown as { id: string }[];
    if (existing.length === 0) {
      this.db
        .prepare(
          'INSERT INTO items (id, sellerId, title, startingPrice, currency, endTime, status, highestBidAmount, highestBidderId, winnerId) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        )
        .run(
          item.id,
          item.sellerId,
          item.title,
          item.startingPrice,
          item.currency,
          item.endTime.toISOString(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
        );
    } else {
      this.db
        .prepare(
          'UPDATE items SET sellerId = ?, title = ?, startingPrice = ?, currency = ?, endTime = ?, status = ?, highestBidAmount = ?, highestBidderId = ?, winnerId = ? WHERE id = ?',
        )
        .run(
          item.sellerId,
          item.title,
          item.startingPrice,
          item.currency,
          item.endTime.toISOString(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
          item.id,
        );
    }
    return item;
  }

  /** Returns the item with the given id, or null when none is stored; throws on an empty id. */
  async findItem(id: string): Promise<Item | null> {
    this.assertId(id, 'id');
    const rows = this.db
      .prepare('SELECT * FROM items WHERE id = ?')
      .all(id) as unknown as ItemRow[];
    return rows.length === 0 ? null : this.toItem(rows[0]);
  }

  /** Returns all items whose status is open. */
  async findOpenItems(): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE status = ?')
      .all(AuctionStatus.open) as unknown as ItemRow[];
    return rows.map((row) => this.toItem(row));
  }

  /** Returns the open items whose end time is at or before the given instant. */
  async findDueItems(now: Date): Promise<Item[]> {
    const open = await this.findOpenItems();
    return open.filter((item) => item.endTime.getTime() <= now.getTime());
  }

  /** Inserts the bid if its id is new, otherwise updates the stored row. */
  async saveBid(bid: Bid): Promise<Bid> {
    const existing = this.db
      .prepare('SELECT id FROM bids WHERE id = ?')
      .all(bid.id) as unknown as { id: string }[];
    if (existing.length === 0) {
      this.db
        .prepare(
          'INSERT INTO bids (id, itemId, bidderId, amount, placedAt) VALUES (?, ?, ?, ?, ?)',
        )
        .run(bid.id, bid.itemId, bid.bidderId, bid.amount, bid.placedAt.toISOString());
    } else {
      this.db
        .prepare(
          'UPDATE bids SET itemId = ?, bidderId = ?, amount = ?, placedAt = ? WHERE id = ?',
        )
        .run(bid.itemId, bid.bidderId, bid.amount, bid.placedAt.toISOString(), bid.id);
    }
    return bid;
  }

  private assertId(value: string, name: string): void {
    if (typeof value !== 'string' || value.length === 0) {
      throw new Error(`${name} must be a non-empty string`);
    }
  }

  private toItem(row: ItemRow): Item {
    return new Item(
      row.id,
      row.sellerId,
      row.title,
      row.startingPrice,
      row.currency as Currency,
      new Date(row.endTime),
      row.status as AuctionStatus,
      row.highestBidAmount,
      row.highestBidderId,
      row.winnerId,
    );
  }
}

import { WebSocket, WebSocketServer } from 'ws';

/**
 * Internal ws endpoint on the API server that fans every published event out to all connected live server instances.
 * @trace DSN-034 REQ-003 REQ-007 REQ-011
 */
export class EventFeed {
  private readonly server: WebSocketServer;
  private readonly clients: Set<WebSocket> = new Set();

  /** Creates the feed and tracks every live server instance that connects to it. */
  constructor() {
    this.server = new WebSocketServer({ noServer: true });
    this.server.on('connection', (socket: WebSocket) => {
      this.clients.add(socket);
      socket.on('close', () => this.clients.delete(socket));
      socket.on('error', () => this.clients.delete(socket));
    });
  }

  /** Sends the event to every connected instance; throws an Error when topic is empty or payload is not a string. */
  publish(topic: string, payload: string): void {
    if (typeof topic !== 'string' || topic.length === 0) {
      throw new Error('topic must be a non-empty string');
    }
    if (typeof payload !== 'string') {
      throw new Error('payload must be a string');
    }
    const message = JSON.stringify({ topic, payload });
    for (const socket of this.clients) {
      if (socket.readyState === WebSocket.OPEN) {
        socket.send(message);
      }
    }
  }
}

