  console.log(`API server listening on port ${port}`);
});

// The event feed owns its ws server (noServer); route upgrades of the internal path to it.
const eventFeed = app.locals.eventFeed as EventFeed;
const feedServer = (eventFeed as unknown as { server: WebSocketServer }).server;
server.on('upgrade', (req: IncomingMessage, socket: Duplex, head: Buffer) => {
  if (req.url === '/internal/live-update-server') {
    feedServer.handleUpgrade(req, socket, head, (ws: WebSocket) => feedServer.emit('connection', ws, req));
  } else {
    socket.destroy();
  }
});

const closer = app.locals.auctionCloser as AuctionCloser;
setInterval(() => {
  closer.tick().catch((error: Error) => console.error(`Closing failed: ${error.message}`));
}, closer.intervalMs);

