import express from 'express';
import { randomUUID } from 'node:crypto';
import { WebSocketServer, type WebSocket } from 'ws';
import { LiveGateway } from '../live-updates/LiveGateway.js';
import { EventFeedClient } from '../live-updates/EventFeedClient.js';

const sockets = new Map<string, WebSocket>();
const liveGateway = new LiveGateway(sockets);
const eventFeedClient = new EventFeedClient(liveGateway);

const app = express();
app.get('/health', (_req, res) => {
  res.json({ status: 'ok' });
});

const port = Number(process.env.LIVE_UPDATE_SERVER_PORT ?? 8081);
const server = app.listen(port, () => {
  console.log(`Live update server listening on port ${port}`);
});

const wss = new WebSocketServer({ server });
wss.on('connection', (socket: WebSocket) => {
  const clientId = randomUUID();
  sockets.set(clientId, socket);
  socket.on('message', (data) => {
    try {
      const msg = JSON.parse(data.toString()) as { action?: string; itemId?: string };
      if (msg.action === 'watch') liveGateway.watch(clientId, String(msg.itemId));
      else if (msg.action === 'unwatch') liveGateway.unwatch(clientId, String(msg.itemId));
    } catch (error) {
      socket.send(JSON.stringify({ error: (error as Error).message }));
    }
  });
  socket.on('close', () => sockets.delete(clientId));
  socket.on('error', () => sockets.delete(clientId));
});

eventFeedClient.connect();

